<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free SQL Formatter Online','description'=>'Format SQL queries with readable line breaks and indentation.','url'=>'https://smarttoolz.in/tools/sql-formatter/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">SQL FORMATTER</span><h1>SQL Formatter</h1><p>Turn long SQL queries into cleaner, readable statements.</p></section><section class="tool-workspace"><div class="tool-panel"><label>SQL query<textarea id="in" rows="14" placeholder="SELECT * FROM users WHERE id = 1"></textarea></label><button id="go" class="tool-btn">Format SQL</button><textarea id="out" rows="14" readonly style="margin-top:15px;width:100%;box-sizing:border-box"></textarea><button id="copy" class="tool-btn" style="margin-top:10px">Copy</button></div></section></main><script>(()=>{const i=document.getElementById('in'),o=document.getElementById('out');document.getElementById('go').onclick=()=>{let s=i.value.replace(/\s+/g,' ').replace(/\s*,\s*/g,', '),k=['SELECT','FROM','WHERE','GROUP BY','ORDER BY','HAVING','LIMIT','LEFT JOIN','RIGHT JOIN','INNER JOIN','OUTER JOIN','JOIN','VALUES','SET'];k.forEach(x=>s=s.replace(new RegExp('\\s*'+x+'\\s*','gi'),'\n'+x+' '));o.value=s.trim()};document.getElementById('copy').onclick=()=>navigator.clipboard.writeText(o.value)})();</script><?php smarttoolz_tool_page_end(); ?>